const inviteMember = `-- name: InviteMember :one
INSERT INTO group_memberships (
  group_id,
  user_id,
  role,
  status,
  invited_by,
  invited_at,
  responded_at,
  joined_at,
  left_at
)
VALUES (
  $1::uuid,
  $2::uuid,
  'member',
  'invited',
  $3::uuid,
  NOW(),
  NULL,
  NULL,
  NULL
)
ON CONFLICT (group_id, user_id)
DO UPDATE SET
  role = CASE
    WHEN group_memberships.role = 'owner' THEN group_memberships.role
    ELSE 'member'
  END,
  status = 'invited',
  invited_by = CASE
    WHEN group_memberships.status = 'invited' THEN group_memberships.invited_by
    ELSE EXCLUDED.invited_by
  END,
  invited_at = CASE
    WHEN group_memberships.status = 'invited' THEN group_memberships.invited_at
    ELSE NOW()
  END,
  responded_at = NULL,
  joined_at = NULL,
  left_at = NULL,
  updated_at = NOW()
WHERE group_memberships.status IN ('invited', 'left', 'declined')
RETURNING
  group_id,
  user_id,
  role,
  status,
  invited_by,
  invited_at,
  responded_at,
  joined_at,
  left_at,
  created_at,
  updated_at,
  ''::text AS username,
  ''::text AS display_name,
  ''::text AS avatar_url
`

