const upsertMembership = `-- name: UpsertMembership :one
INSERT INTO group_memberships (
  group_id,
  user_id,
  role,
  status,
  joined_at,
  left_at,
  responded_at
)
VALUES (
  $1::uuid,
  $2::uuid,
  $3,
  $4,
  CASE WHEN $4 = 'active' THEN NOW() ELSE NULL END,
  NULL,
  CASE WHEN $4 = 'active' THEN NOW() ELSE NULL END
)
ON CONFLICT (group_id, user_id)
DO UPDATE SET
  role = EXCLUDED.role,
  status = EXCLUDED.status,
  joined_at = CASE
    WHEN EXCLUDED.status = 'active' THEN COALESCE(group_memberships.joined_at, NOW())
    ELSE group_memberships.joined_at
  END,
  left_at = CASE
    WHEN EXCLUDED.status = 'active' THEN NULL
    ELSE group_memberships.left_at
  END,
  responded_at = CASE
    WHEN EXCLUDED.status = 'active' THEN NOW()
    ELSE group_memberships.responded_at
  END,
  updated_at = NOW()
WHERE group_memberships.status <> 'blocked'
RETURNING
  group_id,
  user_id,
  role,
  status,
  invited_by,
  invited_at,
  responded_at,
  joined_at,
  left_at,
  created_at,
  updated_at,
  ''::text AS username,
  ''::text AS display_name,
  ''::text AS avatar_url
`

type UpsertMembershipParams struct {
	GroupID pgtype.UUID `db:"group_id" json:"group_id"`
	UserID  pgtype.UUID `db:"user_id" json:"user_id"`
	Role    string      `db:"role" json:"role"`
	Status  string      `db:"status" json:"status"`
}

